With the correct target songs and their existing Brenda reviews, I can now safely decrease higher ratings to 1 and delete any Brenda review that does not already equal 1.

```python
rating_results = []
for song_id in target_song_ids:
    if song_id in own_reviews_by_song:
        for review in own_reviews_by_song[song_id]:
            if review['rating'] > 1:
                update_result = apis.spotify.update_song_review(
                    review_id=review['song_review_id'],
                    access_token=spotify_access_token,
                    rating=1
                )
                rating_results.append({'song_id': song_id, 'action': 'update', 'review_id': review['song_review_id'], 'result': update_result})
            elif review['rating'] == 1:
                rating_results.append({'song_id': song_id, 'action': 'no-op', 'existing_rating': 1})
    else:
        review_result = apis.spotify.review_song(song_id=song_id, rating=1, access_token=spotify_access_token)
        rating_results.append({'song_id': song_id, 'action': 'create', 'result': review_result})
print(rating_results)
```
